from collections import deque
def comps(g,col):
    seen=set(); out=[]
    h,w=len(g),len(g[0])
    for i in range(h):
        for j in range(w):
            if g[i][j]==col and (i,j) not in seen:
                q=deque([(i,j)]); seen.add((i,j)); c=[]
                while q:
                    r,rr=q.popleft(); c.append((r,rr))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=r+dr,rr+dc
                        if 0<=x<h and 0<=y<w and g[x][y]==col and (x,y) not in seen:
                            seen.add((x,y)); q.append((x,y))
                out.append(c)
    return out
