def dihedral(cells):
    s=set(cells)
    outs=[]
    for rot in range(4):
        curr=s
        for refl in range(2):
            outs.add(frozenset(curr))
            outs.add(frozenset((-c,-r) for r,c in curr))
            curr=frozenset((c,-r) for r,c in curr)
